import numpy as np
from rdkit import Chem
def readxyz(f):
    lines=open(f).read().split('\n'); n=int(lines[0])
    els=[];pos=[]
    for l in lines[2:2+n]:
        p=l.split(); els.append(p[0]); pos.append([float(x) for x in p[1:4]])
    return els, np.array(pos)
els,pos = readxyz('opt2.xyz')
n=len(els)
rw = Chem.RWMol()
for e in els: rw.AddAtom(Chem.Atom(e))
fbonds = [(0,1,1),(1,2,1),(2,3,2),(3,4,1),(4,5,1),(5,0,1),
 (1,6,1),(6,7,2),(7,8,1),(8,9,2),(9,10,1),(10,11,2),(11,6,1),
 (5,12,1),(12,13,1),(13,14,1),(14,4,1),
 (4,15,1),(15,16,2),(15,17,1),(17,18,1),(13,19,1),(13,20,1)]
hb = {21:0,22:0,23:1,24:2,25:3,26:5,27:7,28:8,29:9,30:10,31:11,32:18,33:18,34:18,35:19,36:19,37:19,38:20,39:20}
def f(i): return i if i<22 else i-1
bt = {1:Chem.BondType.SINGLE,2:Chem.BondType.DOUBLE,3:Chem.BondType.TRIPLE}
for a,b,t in fbonds: rw.AddBond(a,b,bt[t])
for h,c in hb.items(): rw.AddBond(f(h),c,Chem.BondType.SINGLE)
rw.AddBond(40,0,Chem.BondType.SINGLE)
rw.AddBond(40,41,Chem.BondType.SINGLE)
