rw.AddBond(40,48,Chem.BondType.SINGLE)
rw.AddBond(48,49,Chem.BondType.TRIPLE)
rw.AddBond(49,50,Chem.BondType.SINGLE)
for h in (51,52,53): rw.AddBond(50,h,Chem.BondType.SINGLE)
m = rw.GetMol()
Chem.SanitizeMol(m, Chem.SanitizeFlags.SANITIZE_ALL ^ Chem.SanitizeFlags.SANITIZE_PROPERTIES)
