for i,p in enumerate(pos): conf.SetAtomPosition(i, tuple(map(float,p)))
m.AddConformer(conf)
Chem.AssignStereochemistryFrom3D(m)
for at in m.GetAtoms():
    if at.HasProp('_CIPCode'):
        print("stereo", at.GetIdx(), at.GetSymbol(), at.GetProp('_CIPCode'))
print(Chem.MolToSmiles(Chem.RemoveHs(m)))
